import * as T from './vendor/three.js';
export function makeRoadTextures(){const roads=[];for(let style=0;style<7;style++){const n=512,canvas=document.createElement('canvas');canvas.width=canvas.height=n;const c=canvas.getContext('2d');let seed=501+style*91;const r=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};const base=['#35434e','#5e686e','#737b7d','#59646b','#455560','#a6a497','#a1acaf'][style];c.fillStyle=base;c.fillRect(0,0,n,n);
 for(let i=0;i<(style===0?18000:11000);i++){c.fillStyle=r()>.5?'#d8e3e32b':'#0b1e2b3b';const size=style===2||style===5?1+Math.floor(r()*3):1;c.fillRect(Math.floor(r()*n),Math.floor(r()*n),size,size)}
 if(style<5){for(const x of [n*.24,n*.34,n*.67,n*.77]){c.fillStyle=style===0?'#1c303b18':'#2638431c';c.fillRect(x,0,12,n)}if(style!==0){for(let k=0;k<(style===3?15:5);k++){let x=r()*n,y=r()*n;c.strokeStyle='#26374099';c.lineWidth=1+r();c.beginPath();c.moveTo(x,y);for(let j=0;j<7;j++){x+=r()*17-8;y+=r()*14;c.lineTo(x,y)}c.stroke()}}if(style===3||style===4){for(let i=0;i<(style===3?8:3);i++){const x=20+r()*400,y=r()*480,w=32+r()*95,h=25+r()*100;c.fillStyle=i%2?'#34434a':'#788186';c.fillRect(x,y,w,h);c.strokeStyle='#263b45';c.lineWidth=2;c.strokeRect(x,y,w,h);for(let j=0;j<170;j++){c.fillStyle=r()>.5?'#ffffff15':'#00000012';c.fillRect(x+r()*w,y+r()*h,1,1)}}}if(style===1||style===2){const edge=c.createLinearGradient(0,0,n,0);edge.addColorStop(0,'#ccd2c22b');edge.addColorStop(.12,'#ffffff00');edge.addColorStop(.88,'#ffffff00');edge.addColorStop(1,'#ccd2c22b');c.fillStyle=edge;c.fillRect(0,0,n,n)}if(style===4){c.fillStyle='#87918d';c.fillRect(51,320,112,150);c.strokeStyle='#303f49';c.lineWidth=3;c.strokeRect(51,320,112,150);c.fillStyle='#364a54';c.beginPath();c.arc(390,145,20,0,Math.PI*2);c.fill();c.strokeStyle='#74838a';c.stroke();for(let j=0;j<3;j++)c.fillRect(379,135+j*7,22,3)}}
 if(style===5){for(let i=0;i<7000;i++){const x=r()*n,y=r()*n;c.fillStyle=['#d4d0b9','#8e938c','#bebcae','#6d7b7b'][i%4];c.fillRect(x,y,2+r()*3,1+r()*2)}for(const x of [n*.3,n*.7]){c.fillStyle='#687a7340';c.fillRect(x,0,18,n)}}
 if(style===6){c.fillStyle='#c3cdcf';for(let y=0;y<n;y+=24)for(let x=(y/24)%2?-24:0;x<n;x+=48){c.fillStyle=['#acb7ba','#bfc7c6','#a8b5b7','#c1c9ca'][Math.floor(r()*4)];c.fillRect(x+1,y+1,46,22)}}
 const texture=new T.CanvasTexture(canvas);texture.wrapS=T.ClampToEdgeWrapping;texture.wrapT=T.RepeatWrapping;texture.magFilter=T.NearestFilter;texture.minFilter=T.LinearMipmapLinearFilter;texture.anisotropy=4;texture.colorSpace=T.SRGBColorSpace;roads.push(texture)}return roads}
